package stonytark.cinemarr.screen;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.saveddata.SavedData;
import stonytark.cinemarr.core.platform.CinemarrSettings;
import stonytark.cinemarr.core.server.TelevisionLifecycle;
import stonytark.cinemarr.core.screen.ScreenFacing;
import stonytark.cinemarr.core.screen.ScreenGeometry;
import stonytark.cinemarr.core.screen.ScreenLimits;
import stonytark.cinemarr.core.screen.ScreenPixel;
import stonytark.cinemarr.core.screen.ScreenTopology;
import stonytark.cinemarr.core.video.PresentationMode;

import java.util.*;

public final class CinemarrWorldScreens extends SavedData {
    private final Map<Long,Direction> pixels=new HashMap<>();
    private final Map<Long,Television> televisions=new HashMap<>();
    private final Map<Long,Set<Long>> quickTvConstructions=new HashMap<>();
    private final transient String detachedDimension="detached:"+UUID.randomUUID();
    private transient ServerLevel level;
    private transient boolean registrationsReconciled;
    private transient boolean constructionsRecovered;
    public static CinemarrWorldScreens get(ServerLevel level){CinemarrWorldScreens value=level.getDataStorage().computeIfAbsent(CinemarrWorldScreens::load,CinemarrWorldScreens::new,"cinemarr_screens");value.level=level;if(!value.registrationsReconciled)value.reconcile();if(!value.constructionsRecovered)value.recoverConstructions();return value;}
    public void beginQuickTvConstruction(BlockPos controller,Collection<BlockPos> targets){Set<Long> footprint=new HashSet<>();for(BlockPos target:targets)footprint.add(target.asLong());quickTvConstructions.put(controller.asLong(),footprint);setDirty();}
    public void finishQuickTvConstruction(BlockPos controller){if(quickTvConstructions.remove(controller.asLong())!=null)setDirty();}
    private void recoverConstructions(){if(level==null||quickTvConstructions.isEmpty()){constructionsRecovered=quickTvConstructions.isEmpty();return;}constructionsRecovered=true;boolean changed=false;for(Iterator<Map.Entry<Long,Set<Long>>> builds=quickTvConstructions.entrySet().iterator();builds.hasNext();){Set<Long> footprint=builds.next().getValue();for(Iterator<Long> positions=footprint.iterator();positions.hasNext();){BlockPos pos=BlockPos.of(positions.next());if(!level.hasChunkAt(pos))continue;if(level.getBlockState(pos).is(stonytark.cinemarr.registry.CinemarrBlocks.screenPixel()))level.setBlock(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);positions.remove();changed=true;}if(footprint.isEmpty())builds.remove();}constructionsRecovered=quickTvConstructions.isEmpty();if(changed)setDirty();}
    public void putPixel(BlockPos pos,Direction facing){pixels.put(pos.asLong(),facing);invalidate(pos.asLong());setDirty();}
    public void removePixel(BlockPos pos){pixels.remove(pos.asLong());invalidate(pos.asLong());setDirty();}
    public Television removeController(BlockPos pos){Television removed=televisions.get(pos.asLong());if(removed!=null){TelevisionLifecycle.unregister(removed.id,removed.sessionName);if(television(removed.id)!=null)removeLocal(removed.id);}return removed;}
    public Activation activate(BlockPos controller,UUID owner){BlockPos start=null;for(Direction direction:Direction.values())if(pixels.containsKey(controller.relative(direction).asLong())){start=controller.relative(direction);break;}if(start==null)return new Activation(false,"TV Controller must touch a Screen Pixel");Set<Long> connected=connected(start);List<ScreenPixel> values=values(connected);try{ScreenGeometry geometry=ScreenTopology.analyze(values,limits(),CinemarrSettings.allowIrregularScreens());Television old=televisions.get(controller.asLong());for(Map.Entry<Long,Television> entry:televisions.entrySet())if(entry.getKey()!=controller.asLong()&&intersects(entry.getValue().pixels,connected))return new Activation(false,"Screen pixels already belong to another TV");UUID id=old==null?UUID.randomUUID():old.id,televisionOwner=old==null?owner:old.owner;if(TelevisionLifecycle.overlaps(dimensionKey(),connected,id))return new Activation(false,"Screen pixels already belong to another TV");Television tv=new Television(controller.asLong(),id,televisionOwner,connected,geometry.width(),geometry.height(),geometry.visibilityMask().toByteArray(),geometry.facing(),geometry.minimumU(),geometry.minimumV(),old==null?PresentationMode.FIT:old.presentationMode,old==null?"":old.sessionName,geometry.width(),geometry.height());if(!TelevisionLifecycle.register(registration(tv),CinemarrSettings.maximumScreensPerOwner()))return new Activation(false,old==null?"Maximum screens per owner reached":"TV registration conflicts with another screen");televisions.put(controller.asLong(),tv);setDirty();return new Activation(true,"Activated "+geometry.width()+"x"+geometry.height()+" TV with "+geometry.pixelCount()+" visible pixels");}catch(IllegalArgumentException invalid){return new Activation(false,invalid.getMessage());}}
    public Television television(BlockPos controller){return televisions.get(controller.asLong());}
    public Television television(UUID id){for(Television value:televisions.values())if(value.id.equals(id))return value;return null;}
    public Television removeTelevision(UUID id){Television value=television(id);return value==null?null:removeController(BlockPos.of(value.controllerPos));}
    public List<Television> televisions(){return Collections.unmodifiableList(new ArrayList<>(televisions.values()));}
    public List<Television> televisionsForChunk(ChunkPos chunk){List<Television> found=new ArrayList<>();for(Television tv:televisions.values())for(Long packed:tv.pixels){BlockPos p=BlockPos.of(packed);if((p.getX()>>4)==chunk.x&&(p.getZ()>>4)==chunk.z){found.add(tv);break;}}return found;}
    public boolean overlaps(BlockPos controller,Set<Long> candidates){for(Map.Entry<Long,Television> entry:televisions.entrySet())if(entry.getKey()!=controller.asLong()&&intersects(entry.getValue().pixels,candidates))return true;return false;}
    public int pruneInvalid(){int removed=0;for(Television tv:new ArrayList<>(televisions.values())){LiveValidation validation=liveValidation(tv);if(validation==LiveValidation.INVALID){if(TelevisionLifecycle.unregister(tv.id,tv.sessionName))removed++;else{removeLocal(tv.id);removed++;}}else TelevisionLifecycle.validation(tv.id,validation==LiveValidation.LOADED?TelevisionLifecycle.Validation.LOADED:TelevisionLifecycle.Validation.SAVED);}return removed;}
    public void updatePresentation(BlockPos controller,PresentationMode mode){Television tv=televisions.get(controller.asLong());if(tv!=null&&mode!=null){tv.presentationMode=mode;setDirty();}}
    public void updateSession(BlockPos controller,String name){Television tv=televisions.get(controller.asLong());if(tv!=null){tv.sessionName=name==null?"":name.trim();TelevisionLifecycle.session(tv.id,tv.sessionName);setDirty();}}
    public void updateRendition(BlockPos controller,int width,int height){Television tv=televisions.get(controller.asLong());if(tv!=null&&width>0&&height>0){tv.renditionWidth=width;tv.renditionHeight=height;setDirty();}}
    private Set<Long> connected(BlockPos start){Direction facing=pixels.get(start.asLong());int plane=plane(start,facing);Set<Long> found=new HashSet<>();ArrayDeque<BlockPos> pending=new ArrayDeque<>();pending.add(start);while(!pending.isEmpty()&&found.size()<=CinemarrSettings.maximumScreenPixels()){BlockPos current=pending.removeFirst();long packed=current.asLong();Direction currentFacing=pixels.get(packed);if(currentFacing!=facing||plane(current,facing)!=plane||!found.add(packed))continue;for(Direction direction:Direction.values())if(direction.getAxis()!=facing.getAxis())pending.add(current.relative(direction));}return found;}
    private void invalidate(long pixel){List<Long> invalid=new ArrayList<>();for(Map.Entry<Long,Television> entry:televisions.entrySet())if(entry.getValue().pixels.contains(pixel))invalid.add(entry.getKey());for(Long controller:invalid)removeController(BlockPos.of(controller));}
    private void reconcile(){registrationsReconciled=true;List<Long> invalid=new ArrayList<>();Set<Long> occupied=new HashSet<>();for(Map.Entry<Long,Television> entry:televisions.entrySet()){Television tv=entry.getValue();if(!valid(tv)||intersects(occupied,tv.pixels)||!TelevisionLifecycle.restore(registration(tv)))invalid.add(entry.getKey());else occupied.addAll(tv.pixels);}for(Long controller:invalid)removeLocalAt(controller);if(!invalid.isEmpty())setDirty();}
    private boolean valid(Television tv){try{ScreenGeometry geometry=ScreenTopology.analyze(values(tv.pixels),limits(),CinemarrSettings.allowIrregularScreens());return geometry.width()==tv.width&&geometry.height()==tv.height;}catch(IllegalArgumentException invalid){return false;}}
    private List<ScreenPixel> values(Set<Long> positions){List<ScreenPixel> values=new ArrayList<>();for(Long packed:positions){Direction direction=pixels.get(packed);if(direction==null)throw new IllegalArgumentException("Missing screen pixel");BlockPos p=BlockPos.of(packed);values.add(new ScreenPixel(p.getX(),p.getY(),p.getZ(),ScreenFacing.valueOf(direction.name())));}return values;}
    private LiveValidation liveValidation(Television tv){if(level==null)return LiveValidation.UNLOADED;BlockPos controller=BlockPos.of(tv.controllerPos);if(!level.hasChunkAt(controller))return LiveValidation.UNLOADED;for(Long packed:tv.pixels)if(!level.hasChunkAt(BlockPos.of(packed)))return LiveValidation.UNLOADED;net.minecraft.world.level.block.Block controllerBlock=level.getBlockState(controller).getBlock();if(!(controllerBlock instanceof TvControllerBlock)&&!(controllerBlock instanceof QuickTvBlock))return LiveValidation.INVALID;for(Long packed:tv.pixels){net.minecraft.world.level.block.state.BlockState state=level.getBlockState(BlockPos.of(packed));if(!(state.getBlock() instanceof ScreenPixelBlock)||state.getValue(ScreenPixelBlock.FACING)!=Direction.valueOf(tv.facing.name()))return LiveValidation.INVALID;}return valid(tv)?LiveValidation.LOADED:LiveValidation.INVALID;}
    private TelevisionLifecycle.Registration registration(final Television tv){BlockPos controller=BlockPos.of(tv.controllerPos);return new TelevisionLifecycle.Registration(tv.id,tv.owner,dimensionKey(),tv.controllerPos,controller.getX(),controller.getY(),controller.getZ(),tv.pixels,tv.sessionName,TelevisionLifecycle.Validation.SAVED,()->removeLocal(tv.id));}
    private String dimensionKey(){return level==null?detachedDimension:String.valueOf(level.dimension());}
    private Television removeLocal(UUID id){Television tv=television(id);if(tv!=null){televisions.remove(tv.controllerPos);setDirty();}return tv;}
    private Television removeLocalAt(long controller){Television tv=televisions.remove(controller);if(tv!=null)setDirty();return tv;}
    private enum LiveValidation{LOADED,UNLOADED,INVALID}
    private static ScreenLimits limits(){return new ScreenLimits(CinemarrSettings.minimumScreenPixels(),CinemarrSettings.maximumScreenPixels(),CinemarrSettings.maximumScreenDimension());}
    private static boolean intersects(Set<Long> first,Set<Long> second){for(Long value:first)if(second.contains(value))return true;return false;}
    private static int plane(BlockPos pos,Direction facing){switch(facing.getAxis()){case X:return pos.getX();case Y:return pos.getY();default:return pos.getZ();}}
    @Override public CompoundTag save(CompoundTag tag){tag.putInt("schemaVersion",3);ListTag ps=new ListTag();for(Map.Entry<Long,Direction> e:pixels.entrySet()){CompoundTag v=new CompoundTag();v.putLong("pos",e.getKey());v.putString("facing",e.getValue().name());ps.add(v);}tag.put("pixels",ps);ListTag ts=new ListTag();for(Map.Entry<Long,Television> e:televisions.entrySet()){CompoundTag v=new CompoundTag();v.putLong("controller",e.getKey());e.getValue().save(v);ts.add(v);}tag.put("televisions",ts);ListTag cs=new ListTag();for(Map.Entry<Long,Set<Long>> e:quickTvConstructions.entrySet()){CompoundTag v=new CompoundTag();v.putLong("controller",e.getKey());long[] values=new long[e.getValue().size()];int i=0;for(Long pixel:e.getValue())values[i++]=pixel;v.putLongArray("pixels",values);cs.add(v);}tag.put("quickTvConstructions",cs);return tag;}
    public static CinemarrWorldScreens load(CompoundTag tag){CinemarrWorldScreens data=new CinemarrWorldScreens();ListTag ps=tag.getList("pixels",Tag.TAG_COMPOUND);for(int i=0;i<ps.size();i++){CompoundTag v=ps.getCompound(i);try{data.pixels.put(v.getLong("pos"),Direction.valueOf(v.getString("facing")));}catch(IllegalArgumentException ignored){}}ListTag ts=tag.getList("televisions",Tag.TAG_COMPOUND);for(int i=0;i<ts.size();i++){CompoundTag v=ts.getCompound(i);Television tv=Television.load(v,v.getLong("controller"));if(tv!=null)data.televisions.put(tv.controllerPos,tv);}ListTag cs=tag.getList("quickTvConstructions",Tag.TAG_COMPOUND);for(int i=0;i<cs.size();i++){CompoundTag v=cs.getCompound(i);Set<Long> positions=new HashSet<>();for(long pixel:v.getLongArray("pixels"))positions.add(pixel);if(!positions.isEmpty())data.quickTvConstructions.put(v.getLong("controller"),positions);}return data;}
    public static final class Television {private final long controllerPos;private final UUID id,owner;private final Set<Long> pixels;private final int width,height;private final byte[] mask;private final ScreenFacing facing;private final int minimumU,minimumV;private PresentationMode presentationMode;private String sessionName;private int renditionWidth,renditionHeight;Television(long controller,UUID id,UUID owner,Set<Long> pixels,int width,int height,byte[] mask,ScreenFacing facing,int minimumU,int minimumV,PresentationMode mode,String session,int renditionWidth,int renditionHeight){this.controllerPos=controller;this.id=id;this.owner=owner;this.pixels=new HashSet<>(pixels);this.width=width;this.height=height;this.mask=mask.clone();this.facing=facing;this.minimumU=minimumU;this.minimumV=minimumV;this.presentationMode=mode;this.sessionName=session;this.renditionWidth=renditionWidth>0?renditionWidth:width;this.renditionHeight=renditionHeight>0?renditionHeight:height;}public UUID id(){return id;}public long controllerPos(){return controllerPos;}public UUID owner(){return owner;}public Set<Long> pixels(){return Collections.unmodifiableSet(pixels);}public int width(){return width;}public int height(){return height;}public int renditionWidth(){return renditionWidth;}public int renditionHeight(){return renditionHeight;}public byte[] mask(){return mask.clone();}public ScreenFacing facing(){return facing;}public int minimumU(){return minimumU;}public int minimumV(){return minimumV;}public int plane(){return CinemarrWorldScreens.plane(BlockPos.of(pixels.iterator().next()),Direction.valueOf(facing.name()));}public PresentationMode presentationMode(){return presentationMode;}public String sessionName(){return sessionName;}void save(CompoundTag tag){tag.putUUID("id",id);tag.putUUID("owner",owner);tag.putInt("width",width);tag.putInt("height",height);tag.putInt("renditionWidth",renditionWidth);tag.putInt("renditionHeight",renditionHeight);tag.putByteArray("mask",mask);tag.putString("facing",facing.name());tag.putInt("minimumU",minimumU);tag.putInt("minimumV",minimumV);tag.putString("presentationMode",presentationMode.name());tag.putString("sessionName",sessionName);long[] values=new long[pixels.size()];int i=0;for(Long pixel:pixels)values[i++]=pixel;tag.putLongArray("pixels",values);}static Television load(CompoundTag tag,long controller){if(!tag.hasUUID("id")||!tag.hasUUID("owner"))return null;Set<Long> pixels=new HashSet<>();for(long pixel:tag.getLongArray("pixels"))pixels.add(pixel);try{return new Television(controller,tag.getUUID("id"),tag.getUUID("owner"),pixels,tag.getInt("width"),tag.getInt("height"),tag.getByteArray("mask"),ScreenFacing.valueOf(tag.getString("facing")),tag.getInt("minimumU"),tag.getInt("minimumV"),tag.contains("presentationMode")?PresentationMode.valueOf(tag.getString("presentationMode")):PresentationMode.FIT,tag.getString("sessionName"),tag.contains("renditionWidth")?tag.getInt("renditionWidth"):tag.getInt("width"),tag.contains("renditionHeight")?tag.getInt("renditionHeight"):tag.getInt("height"));}catch(IllegalArgumentException invalid){return null;}}}
    public static final class Activation {private final boolean success;private final String message;Activation(boolean success,String message){this.success=success;this.message=message;}public boolean success(){return success;}public String message(){return message;}}
}
